"""
planner.py - Task Dependency Planner

This module provides functionality to plan tasks with durations and dependencies.
It supports computing topological order, critical path, slack time for each task, and generating a textual Gantt chart.
"""

from collections import deque, defaultdict

class Task:
    """Represents a task with a name, duration, and dependencies."""
    def __init__(self, name, duration, dependencies=None):
        self.name = name
        self.duration = duration
        self.dependencies = dependencies if dependencies else []

class Planner:
    """Task dependency planner to compute schedule metrics and visualize as Gantt chart."""
    def __init__(self, tasks):
        """Initialize with a list of Task objects."""
        self.tasks = {task.name: task for task in tasks}
        self.adj = defaultdict(list)  # task -> list of dependent tasks
        self.indegree = defaultdict(int)  # task name -> number of dependencies
        self._build_graph()

    def _build_graph(self):
        """Build internal graph representation from tasks."""
        for task in self.tasks.values():
            self.indegree[task.name] = len(task.dependencies)
            for dep in task.dependencies:
                self.adj[dep].append(task.name)

    def topological_order(self):
        """Return a list of task names in topological order."""
        order = []
        q = deque([t for t, deg in self.indegree.items() if deg == 0])
        while q:
            u = q.popleft()
            order.append(u)
            for v in self.adj[u]:
                self.indegree[v] -= 1
                if self.indegree[v] == 0:
                    q.append(v)
        if len(order) != len(self.tasks):
            raise ValueError("Cycle detected in task dependencies.")
        return order

    def critical_path(self):
        """Calculate the critical path and earliest start/finish times."""
        order = self.topological_order()

        earliest_start = {t: 0 for t in self.tasks}
        earliest_finish = {}

        # Forward pass
        for u in order:
            earliest_finish[u] = earliest_start[u] + self.tasks[u].duration
            for v in self.adj[u]:
                if earliest_start[v] < earliest_finish[u]:
                    earliest_start[v] = earliest_finish[u]

        max_finish = max(earliest_finish.values())

        # Backward pass for latest start/finish
        latest_finish = {t: max_finish for t in self.tasks}
        latest_start = {}

        for u in reversed(order):
            latest_start[u] = latest_finish[u] - self.tasks[u].duration
            for v in self.adj[u]:
                if latest_finish[u] > latest_start[v]:
                    latest_finish[u] = latest_start[v]

        # Calculate slack
        slack = {t: latest_start[t] - earliest_start[t] for t in self.tasks}

        return {
            'earliest_start': earliest_start,
            'earliest_finish': earliest_finish,
            'latest_start': latest_start,
            'latest_finish': latest_finish,
            'slack': slack,
            'critical_path_duration': max_finish
        }

    def gantt_chart(self):
        """Return a multiline string with a textual Gantt chart."""
        import math

        cp = self.critical_path()
        earliest_start = cp['earliest_start']
        durations = {t: self.tasks[t].duration for t in self.tasks}
        max_time = cp['critical_path_duration']

        lines = []
        # Header
        header = "Time:" + "".join(f"{i:2}" for i in range(max_time))
        lines.append(header)
        # Tasks
        for t in self.topological_order():
            line = f"{t:6}:"
            start = earliest_start[t]
            duration = durations[t]
            for time in range(max_time):
                if start <= time < start + duration:
                    line += "# "
                else:
                    line += ". "
            lines.append(line)
        return "\n".join(lines)

if __name__ == '__main__':
    # Demo usage
    tasks = [
        Task('A', 3),
        Task('B', 2, ['A']),
        Task('C', 4, ['A']),
        Task('D', 2, ['B', 'C']),
        Task('E', 1, ['D']),
    ]

    planner = Planner(tasks)
    print("Topological Order:", planner.topological_order())
    cp = planner.critical_path()
    print("Critical Path Duration:", cp['critical_path_duration'])
    print("Slack per task:", cp['slack'])
    print("Gantt Chart:\n", planner.gantt_chart())
